import type { ArtStyle } from '../types';
import { CLASSIC_FEATURES } from '../types';

/**
 * The original look. Its textures are still generated by BootScene, campaignThemes.ts and
 * EnemyTextureGenerator under their historic keys, and every new-style feature is off.
 */
export const classicStyle: ArtStyle = {
  id: 'classic',
  features: CLASSIC_FEATURES,
  // Loaded on demand: its Canvas2D helpers import BootScene (and so Phaser).
  drawPreview: (canvas) => {
    void import('../classicPreview').then((m) => m.drawClassicPreview(canvas));
  },
};
